import{z as B,x as A,o as i,c as d,q as o,j as E,D as s,d as e,s as n,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"目录协议的扩展性","description":"","frontmatter":{"title":"目录协议的扩展性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/directory-scalability.md","filePath":"cs/directory-scalability.md","lastUpdated":1791063341000}'),m={name:"cs/directory-scalability.md"};function p(h,a,c,D,C,u){const t=A("Mermaid");return i(),d("div",null,[a[2]||(a[2]=o('<h1 id="目录协议的扩展性" tabindex="-1">目录协议的扩展性 <a class="header-anchor" href="#目录协议的扩展性" aria-label="Permalink to &quot;目录协议的扩展性&quot;">​</a></h1><div class="epigraph"><p>窥探要求每个缺失让所有 cache 听见；目录记下谁可能有副本，只向那几个节点发点对点请求，流量随共享集而不是随核数涨。</p><footer>—— 据 Censier and Feautrier；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/moesi-mesif">上一课</a> 在广播总线上加了 O/F。核数到几十上百时，即使 F 减少重复数据，<strong>地址事务仍要人人听</strong>。本课不重画五态。缺口是<strong>目录：每行（或每组）一份 sharer 向量 / 指针，把一致性从广播改成端到端。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窥探带宽 ∝ 核数 × miss 率。互连变成广播介质后，<a href="/cs/mlp-memory-parallelism">MLP</a> 越高越堵。缺口不是再加一个 Forward 态，而是<strong>用存储换广播：目录项指出可能的副本集合。</strong> 目录本身要分区到 LLC slice 或 memory controller，否则又成为单点。</p><p><span class="marginnote">完整位向量：每核一位，精确但随核数线性涨。稀疏目录：少量指针，溢出则广播或退化为粗向量。这是面积与无效流量的交易。</span></p><p><span class="marginnote">数字实例：64 核机器上某行只被 3 个核共享。窥探作废要广播给全部 64 个核（63 份纯属陪听）；目录查 sharer 向量「…00101」只点对点发 2 份 invalidate、收 2 个 ack。请求量从 63 降到 2，这就是「流量随共享集而不是随核数涨」的具体含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 miss：向 home 目录要数据与权限；目录把请求者加入 sharer，若存在 owner 则转发。写 miss：目录向所有 sharer 发 invalidate，收集 ack，再给请求者 M。替换：通知目录删 sharer，脏则写回。</p>',9)),(i(),E(l,null,{default:s(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%A0%B8%20miss%22%5D%20--%3E%20HOME%5B%22%E8%AF%A5%E8%A1%8C%E7%9A%84%E7%9B%AE%E5%BD%95%20home%22%5D%0A%20%20HOME%20--%3E%20FWD%5B%22%E8%BD%AC%E5%8F%91%E5%88%B0%20owner%20%2F%20%E8%AE%B0%E5%BF%86%E4%BD%93%22%5D%0A%20%20HOME%20--%3E%20INV%5B%22%E7%82%B9%E5%AF%B9%E7%82%B9%E4%BD%9C%E5%BA%9F%20sharer%22%5D%0A%20%20INV%20--%3E%20ACK%5B%22%E6%94%B6%E9%9B%86%20ack%20%E5%86%8D%E6%8E%88%E6%9D%83%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("延迟从「一跳广播」变成「到 home 再可能到 owner」，跳数增加，但带宽可扩展。与 "),r("a",{href:"/cs/moesi-mesif"},"MOESI"),e(" 组合：目录里存 owner 指针而不是只存 S 集合。伪共享表现为同一目录项上的频繁 inv，协议正确、性能差。")],-1)),a[5]||(a[5]=r("p",null,"目录存储与 LLC 标签可共存（in-cache directory）：行在 LLC 则目录免费，被踢出则要写回或记 overflow。",-1)),(i(),E(l,null,{default:s(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SN%5B%22%E7%AA%A5%E6%8E%A2%EF%BC%9A%E5%B9%BF%E6%92%AD%22%5D%0A%20%20%20%20M1%5B%22%E4%BB%BB%E4%B8%80%E6%A0%B8%20miss%22%5D%20--%3E%20BUS%5B%22%E6%80%BB%E7%BA%BF%E5%B9%BF%E6%92%AD%22%5D%0A%20%20%20%20BUS%20--%3E%20C1%5B%22%E6%A0%B8%200%20%E8%A2%AB%E8%BF%AB%E5%90%AC%22%5D%0A%20%20%20%20BUS%20--%3E%20C2%5B%22%E6%A0%B8%201%20%E8%A2%AB%E8%BF%AB%E5%90%AC%22%5D%0A%20%20%20%20BUS%20--%3E%20C3%5B%22%E2%80%A6%E2%80%A6%E5%85%B6%E4%BD%99%2061%20%E6%A0%B8%E4%B9%9F%E8%A2%AB%E8%BF%AB%E5%90%AC%22%5D%0A%20%20end%0A%20%20subgraph%20DIRN%5B%22%E7%9B%AE%E5%BD%95%EF%BC%9A%E7%82%B9%E5%AF%B9%E7%82%B9%22%5D%0A%20%20%20%20M2%5B%22%E6%A0%B8%205%20miss%22%5D%20--%3E%20HOME2%5B%22home%20%E6%9F%A5%20sharer%20%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%0A%20%20%20%20HOME2%20--%3E%7C%22%E5%8F%AA%E5%8F%91%E5%85%B1%E4%BA%AB%E6%A0%B8%22%7C%20P1%5B%22%E6%A0%B8%202%20invalidate%22%5D%0A%20%20%20%20HOME2%20--%3E%20P2%5B%22%E6%A0%B8%207%20invalidate%22%5D%0A%20%20end%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>这张图回答「目录到底省掉了什么」：同样的写 miss，窥探让 63 个不相干核都花监听带宽，目录只打扰向量里为 1 的那几位。代价是多一跳（先到 home 再到 owner/sharer）和每行一份向量存储——用延迟和面积换回带宽的可扩展性。</p><p><span class="marginnote">术语翻译：sharer 向量就是这行缓存的「名单」——一串二进制位，第 \\(i\\) 位是 1 表示「核 \\(i\\) 手里可能有副本」，作废时照名单点名，不搞全班广播。</span></p><p><span class="marginnote">常见误区：初学者容易把目录想成「集群门口的一张总表」。实际上目录按地址切片分散到各个 LLC slice / 内存控制器上（每条地址固定归属一个 slice），否则这张表自己就成了比总线更糟的单点——这正是「home 必须分区」的意思。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某种 NoC 拓扑定成唯一 home 映射，后课 mesh 会决定 slice 怎么放。也不处理死锁的虚通道，那是 NoC 路由课。原子与 acquire/release 建立在「行已按目录拿到合适态」之上，随后几课。</p><p>后课默认：大规模用目录；共享集溢出才广播。同一行上无关变量互踢，是下一课伪共享。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>目录用 sharer 集合代替广播监听，换存储与多跳延迟。</li><li>home 必须分区，否则单点。</li><li>行粒度上的虚假争用是下一课伪共享。</li><li>出处：Censier and Feautrier；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const _=B(m,[["render",p]]);export{F as __pageData,_ as default};
